public class Main {
    public static void main(String[] args) {
        int num = 13579;
        int sum = 0;
        int n = num;
        do {
            int digit = n % 10;
            System.out.print(digit);
            sum += digit;
            n /= 10;
            if (n > 0) {
                System.out.print("+");
            } else {
                System.out.print("=");
                System.out.print(sum);
            }
        } while (n > 0);
    }
}

