class MyException extends Exception {
    MyException(String msg) { super(msg); }
}
public class Main {
    public static void main(String[] args) {
        int result = 0;
        try {
            result = check(-5);
        } catch (MyException e) {
            result = -1;
        } catch (ArithmeticException e) {
            result = -2;
        }
        System.out.print(result);
    }
    static int check(int n) throws MyException {
        if (n < 0) throw new MyException("negative");
        return n * 2;
    }
}

